                                                                                                                                                                                                                                                                                                                                                                                                             
  CREATE OR REPLACE FORCE EDITIONABLE VIEW "MPF_SHARE_BASIC_USER_INFO_V" ("USER_ID", "TENANT_ID", "EXTRA_USER_ID", "UNION_ID", "TITLE", "NAME", "AVATAR", "STATE_CODE", "MOBILE", "JOB_NUMBER", "EMAIL", "IS_LEAVE", "HIRED_DATE", "LEADER_EXTRA_USER_ID", "LEADER_USER_NAME", "LEADER_USER_ID", "DEPT_ID", "DEPT_NAME", "IS_LEADER", "MAIN_DEPT_ORDER", "DEPT_ORDER", "BASE_DEPT_ID") AS         
  select USER_ID,                                                                                                                                                                                                                                                                                                                                                                                            
       TENANT_ID,                                                                                                                                                                                                                                                                                                                                                                                            
       EXTRA_USER_ID,                                                                                                                                                                                                                                                                                                                                                                                        
       UNION_ID,                                                                                                                                                                                                                                                                                                                                                                                             
       TITLE,                                                                                                                                                                                                                                                                                                                                                                                                
       NAME,                                                                                                                                                                                                                                                                                                                                                                                                 
       AVATAR,                                                                                                                                                                                                                                                                                                                                                                                               
       STATE_CODE,                                                                                                                                                                                                                                                                                                                                                                                           
       MOBILE,                                                                                                                                                                                                                                                                                                                                                                                               
       JOB_NUMBER,                                                                                                                                                                                                                                                                                                                                                                                           
       EMAIL,                                                                                                                                                                                                                                                                                                                                                                                                
       IS_LEAVE,                                                                                                                                                                                                                                                                                                                                                                                             
       HIRED_DATE,                                                                                                                                                                                                                                                                                                                                                                                           
       LEADER_EXTRA_USER_ID,                                                                                                                                                                                                                                                                                                                                                                                 
       LEADER_USER_NAME,                                                                                                                                                                                                                                                                                                                                                                                     
       LEADER_USER_ID,                                                                                                                                                                                                                                                                                                                                                                                       
       DEPT_ID AS   DEPT_ID,                                                                                                                                                                                                                                                                                                                                                                                 
       DEPT_NAME,                                                                                                                                                                                                                                                                                                                                                                                            
       IS_LEADER,                                                                                                                                                                                                                                                                                                                                                                                            
       MAIN_DEPT_ORDER,                                                                                                                                                                                                                                                                                                                                                                                      
       DEPT_ORDER,                                                                                                                                                                                                                                                                                                                                                                                           
       BASE_DEPT_ID                                                                                                                                                                                                                                                                                                                                                                                          
from MPF.SHARE_OPS_USER_INFO_V                                                                                                                                                                                                                                                                                                                                                                               
where MAIN_DEPT_ORDER = 0;                                                                                                                                                                                                                                                                                                                                                                                   

